            }

            r = HAL_RCC_HCPU_SwitchDvfsS2D(new_dvfs_mode, freq_in_mhz);
        }
        break;
    }
    default:
    {
        r = HAL_ERROR;
        goto __EXIT;
    }
    }

    curr_dvfs_mode = new_dvfs_mode;
    curr_freq_in_mhz = freq_in_mhz;
    HAL_Delay_us(0);

__EXIT:
    return r;
}


