/****************************************************************************
 * Name: pm_initialize
 *
 * Description:
 *   This function is called by MCU-specific one-time at power on reset in
 *   order to initialize the power management capabilities.  This function
 *   must be called *very* early in the initialization sequence *before* any
 *   other device drivers are initialize (since they may attempt to register
 *   with the power management subsystem).
 *
 * Input Parameters:
 *   None.
 *
 * Returned Value:
 *    None.
 *
 ****************************************************************************/

void pm_initialize(void)
{
  FAR const struct pm_governor_s *gov;
#if CONFIG_PM_GOVERNOR_EXPLICIT_RELAX
  int state;
#endif
  int i;

  pm_wakelock_global_init();

  /* Select governor */

  for (i = 0; i < CONFIG_PM_NDOMAINS; i++)
    {
#if defined(CONFIG_PM_GOVERNOR_GREEDY)
      gov = pm_greedy_governor_initialize();
#elif defined(CONFIG_PM_GOVERNOR_ACTIVITY)
      gov = pm_activity_governor_initialize();
#elif defined(CONFIG_PM_GOVERNOR_STABILITY)
      gov = pm_stability_governor_initialize();
#else
      static struct pm_governor_s null;
      gov = &null;
#endif
      pm_set_governor(i, gov);

#if defined(CONFIG_PM_STAT)
      clock_systime_timespec(&g_pmdomains[i].start);
#endif

      spin_lock_init(&g_pmdomains[i].lock);

#if CONFIG_PM_GOVERNOR_EXPLICIT_RELAX
      for (state = 0; state < PM_COUNT; state++)
        {
#  if CONFIG_PM_GOVERNOR_EXPLICIT_RELAX < 0
          pm_stay(i, state);
#  else
          pm_staytimeout(i, state, CONFIG_PM_GOVERNOR_EXPLICIT_RELAX);
#  endif
        }
#endif
    }
}

 *   handler - The execution after cpu and system domain state changed.
 *
 * Returned Value:
 *   None.
 *
 ****************************************************************************/

void pm_idle(pm_idle_handler_t handler)
{
  enum pm_state_e systemstate;
  enum pm_state_e oldstate;
  enum pm_state_e newstate;
  irqstate_t flags;
  int domain;
  bool first;
  bool last;
  int cpu;
  int ret;

  systemstate = PM_RESTORE;
  cpu         = this_cpu();
  domain      = PM_SMP_CPU_DOMAIN(cpu);

  /* If sched lock before irq save, and irq handler do post, scheduler will
   * be delayed after WFI until next sched unlock. which is not acceptable.
   */

  flags = up_irq_save();
  sched_lock();

  oldstate = pm_querystate(domain);
  newstate = pm_checkstate(domain);

  ret = pm_changestate(domain, newstate);
  if (ret < 0)
    {
      newstate = oldstate;
    }

  if (oldstate != newstate)
    {
      pm_stay(PM_IDLE_DOMAIN, newstate);
      if (CPU_ISSET(cpu, &g_pm_idle.firstdone))
        {
          pm_relax(PM_IDLE_DOMAIN, oldstate);
        }
      else
        {
          spin_lock(&g_pm_idle.lock);
          CPU_SET(cpu, &g_pm_idle.firstdone);
          spin_unlock(&g_pm_idle.lock);
        }
    }

  spin_lock(&g_pm_idle.lock);
  CPU_CLR(cpu, &g_pm_idle.running);
  last = (g_pm_idle.running == 0);

#if CONFIG_PM_SMP_LAST_CPU_INDEX >= 0
  if (last && cpu != CONFIG_PM_SMP_LAST_CPU_INDEX)
    {
      nxsched_smp_call_single_async(CONFIG_PM_SMP_LAST_CPU_INDEX,
                                    &g_pm_idle.smp_call_data);
      last = false;
    }
#endif

  if (last)
    {
      last = pm_idle_checkstate(cpu);
    }

  if (last)
    {
      systemstate = pm_checkstate(PM_IDLE_DOMAIN);
      ret         = pm_changestate(PM_IDLE_DOMAIN, systemstate);
      if (ret < 0)
        {
          systemstate = PM_NORMAL;
        }
    }

  first = handler(cpu, newstate, systemstate);

  if (first)
    {
      pm_changestate(PM_IDLE_DOMAIN, PM_RESTORE);
    }

  spin_unlock(&g_pm_idle.lock);
  pm_changestate(domain, PM_RESTORE);

  /* If there is pending irq, enable irq make handlers finish all
   * execution will be better decrease scheduler context switch times.
   */

  up_irq_restore(flags);
  sched_unlock();
}

